  style: 'currency',
  currency: 'USD',
  maximumFractionDigits: 0
});

const numberFormatter = new Intl.NumberFormat('en-US');

const dateFormatter = new Intl.DateTimeFormat('en-US', {
  month: 'short',
  day: '2-digit',
  hour: '2-digit',
  minute: '2-digit'
});

export default async function Page() {
  const catalog = await getCatalogSnapshot();

  async function syncCatalogAction() {
    'use server';
    void syncCatalogInBackground();
  }

  const lastSyncLabel = dateFormatter.format(new Date(catalog.generatedAt));

  return (
    <main className={`${spaceGrotesk.variable} ${fraunces.variable} catalog-page`}>
      <header className="catalog-hero">
        <div>
          <p className="eyebrow">Admin Console - Product Catalog</p>
          <h1 className="catalog-title">Catalog Control Center</h1>
          <p className="catalog-subtitle">
            Read-optimized catalog view with cached snapshots. Sync runs in the background so
            operators can keep moving while data settles.
          </p>
          <div className="hero-meta">
            <div>
              <span className="meta-label">Last snapshot</span>
              <span className="meta-value">{lastSyncLabel}</span>
