            <p className="sync-panel-footnote">
              Large updates are processed in batches to keep the UI responsive.
            </p>
          </div>
        </div>
      </header>

      <section className="stats-grid">
        <div className="stat-card">
          <p className="stat-label">Total SKUs</p>
          <p className="stat-value">{numberFormatter.format(catalog.totals.totalSkus)}</p>
          <p className="stat-footnote">Cached snapshot</p>
        </div>
        <div className="stat-card">
          <p className="stat-label">Units in stock</p>
          <p className="stat-value">{numberFormatter.format(catalog.totals.totalUnits)}</p>
          <p className="stat-footnote">
            {numberFormatter.format(catalog.totals.inStock)} SKUs available
          </p>
        </div>
        <div className="stat-card">
          <p className="stat-label">Low stock</p>
          <p className="stat-value">{numberFormatter.format(catalog.totals.lowStock)}</p>
          <p className="stat-footnote">Below {LOW_STOCK_THRESHOLD} units</p>
        </div>
        <div className="stat-card">
          <p className="stat-label">Inventory value</p>
          <p className="stat-value">{currencyFormatter.format(catalog.totals.inventoryValue)}</p>
          <p className="stat-footnote">Current cached value</p>
        </div>
      </section>

      <section className="table-card">
        <div className="table-header">
          <div>
            <h2>Product list</h2>
            <p className="table-subtitle">
              Snapshot is cached with the <span className="mono">products</span> tag and updated
