            </p>
          </div>
          <div className="table-actions">
            <input className="search-input" placeholder="Search SKU, name, or category" />
            <button className="btn btn-ghost" type="button">
              Export CSV
            </button>
          </div>
        </div>
        <div className="table-scroll">
          <table className="catalog-table">
            <thead>
              <tr>
                <th>SKU</th>
                <th>Product</th>
                <th>Category</th>
                <th>Status</th>
                <th>Inventory</th>
                <th>Price</th>
                <th>Updated</th>
              </tr>
            </thead>
            <tbody>
