                const isOut = product.inventory === 0;
                const isLow = product.inventory > 0 && product.inventory < LOW_STOCK_THRESHOLD;
                const statusLabel = isOut ? 'Out of stock' : isLow ? 'Low stock' : 'In stock';
                const statusClass = isOut ? 'badge danger' : isLow ? 'badge warn' : 'badge success';

                return (
                  <tr key={product.id}>
                    <td className="mono">{product.sku}</td>
                    <td>
                      <div className="product-name">{product.name}</div>
                    </td>
                    <td>{product.category}</td>
                    <td>
                      <span className={statusClass}>{statusLabel}</span>
                    </td>
                    <td>{numberFormatter.format(product.inventory)}</td>
                    <td>{currencyFormatter.format(product.price)}</td>
                    <td>{dateFormatter.format(new Date(product.updatedAt))}</td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>
      </section>

      <style jsx global>{`
